<template><div class="app-container"><el-row :gutter="10" class="mb8"><el-col :span="1.5"><el-button v-hasPermi="['library:course:code']" type="primary" plain size="mini" @click="visible=true">批量生成课程码</el-button></el-col><right-toolbar :search="false" @queryTable="$refs.courseCodeList.loadData()" /></el-row><simple-list ref="courseCodeList" plain embedded title="课程码记录（仅显示掩码）" :loader="listCourseCodes" :columns="columns"/><el-dialog title="批量生成课程码" :visible.sync="visible"><el-form label-width="100px"><el-form-item label="课程编号" required><el-input-number v-model="form.courseId" :min="1"/></el-form-item><el-form-item label="生成数量" required><el-input-number v-model="form.count" :min="1" :max="1000"/></el-form-item></el-form><el-alert v-if="codes.length" title="以下明文只展示一次，请立即安全导出。" type="warning" :closable="false"/><el-input v-if="codes.length" :value="codes.join('\n')" type="textarea" :rows="10" readonly class="mt16"/><span slot="footer"><el-button @click="visible=false">关闭</el-button><el-button v-if="!codes.length" type="primary" @click="generate">生成</el-button></span></el-dialog></div></template>
<script>import SimpleList from '@/views/library/common/SimpleList';import { listCourseCodes,generateCourseCodes } from '@/api/library/course';export default{name:'LibraryCourseCode',components:{SimpleList},data(){return{listCourseCodes,visible:false,form:{courseId:1,count:10},codes:[],columns:[{prop:'codeMask',label:'课程码掩码'},{prop:'courseId',label:'课程编号'},{prop:'batchNo',label:'批次号',width:220},{prop:'status',label:'状态'},{prop:'usedUserId',label:'使用用户'}]}},methods:{generate(){generateCourseCodes(this.form).then(r=>{this.codes=(r.data&&r.data.plaintextCodes)||[]})}}}</script><style scoped>.mt16{margin-top:16px}</style>
